<?php require_login(['admin']);$pdo=db();$keys=['school_name','campus','phone','email','address','motto','ceo'];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($keys as $k)$s->execute([$k,trim($_POST[$k]??'')]);flash('success','Settings saved.');redirect('index.php?page=settings');}?><section class="panel"><h2>School Settings</h2><form class="form-grid" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>School Name<input name="school_name" value="<?=e(setting('school_name',SCHOOL_NAME))?>"></label><label>Campus<input name="campus" value="<?=e(setting('campus',CAMPUS))?>"></label><label>Phone<input name="phone" value="<?=e(setting('phone',PHONE))?>"></label><label>Email<input type="email" name="email" value="<?=e(setting('email',EMAIL))?>"></label><label>Address<input name="address" value="<?=e(setting('address',ADDRESS))?>"></label><label>Motto<input name="motto" value="<?=e(setting('motto','Join Us & Change the World'))?>"></label><label>CEO<input name="ceo" value="<?=e(setting('ceo','Ali Akbar Soomro'))?>"></label><button class="btn primary wide">Save Settings</button></form></section>
